import React, { useEffect, useState } from "react";
import "./Board.css";
import Tile from "./Tile";

import sprite0 from "../assets/sprite_0.svg";
import sprite1 from "../assets/sprite_1.svg";
import sprite2 from "../assets/sprite_2.svg";
import sprite3 from "../assets/sprite_3.svg";
import sprite4 from "../assets/sprite_4.svg";
import sprite5 from "../assets/sprite_5.svg";
import sprite6 from "../assets/sprite_6.svg";

const width = 8;

const tileTypes = [
  { name: "sprite_0", img: sprite0 },
  { name: "sprite_1", img: sprite1 },
  { name: "sprite_2", img: sprite2 },
  { name: "sprite_3", img: sprite3 },
  { name: "sprite_4", img: sprite4 },
  { name: "sprite_5", img: sprite5 },
  { name: "sprite_6", img: sprite6 },
];

const getRandomTile = () =>
  tileTypes[Math.floor(Math.random() * tileTypes.length)];

const createBoard = () =>
  Array.from({ length: width * width }, () => getRandomTile());

const Board = () => {
  const [board, setBoard] = useState([]);
  const [selected, setSelected] = useState(null);
  const [animating, setAnimating] = useState(false);

  useEffect(() => {
    const { newBoard } = handleMatches(createBoard());
    setBoard(newBoard);
  }, []);

  const getAllMatches = (board) => {
    const matchedIndices = new Set();
    for (let i = 0; i < width * width; i++) {
      const base = board[i];
      if (!base) continue;
      const name = base.name;

      for (let offset = 2; offset <= 4; offset++) {
        if (i % width <= width - offset - 1) {
          const group = Array.from({ length: offset + 1 }, (_, k) => i + k);
          if (group.every(idx => board[idx]?.name === name)) {
            group.forEach(idx => matchedIndices.add(idx));
          }
        }
        if (i < width * (width - offset)) {
          const group = Array.from({ length: offset + 1 }, (_, k) => i + k * width);
          if (group.every(idx => board[idx]?.name === name)) {
            group.forEach(idx => matchedIndices.add(idx));
          }
        }
      }

      if (
        i % width < width - 2 &&
        i < width * (width - 2) &&
        board[i + 1]?.name === name &&
        board[i + 2]?.name === name &&
        board[i + width]?.name === name &&
        board[i + width * 2]?.name === name
      ) {
        matchedIndices.add(i);
        matchedIndices.add(i + 1);
        matchedIndices.add(i + 2);
        matchedIndices.add(i + width);
        matchedIndices.add(i + width * 2);
      }
    }
    return matchedIndices;
  };

  const handleMatches = (currentBoard) => {
    let newBoard = [...currentBoard];
    let matched;
    let anyMatch = false;

    do {
      matched = getAllMatches(newBoard);
      if (matched.size === 0) break;
      anyMatch = true;
      matched.forEach(idx => newBoard[idx] = null);

      for (let row = width - 1; row >= 0; row--) {
        for (let col = 0; col < width; col++) {
          const i = row * width + col;
          if (newBoard[i] === null) {
            let aboveRow = row - 1;
            while (aboveRow >= 0) {
              const aboveIdx = aboveRow * width + col;
              if (newBoard[aboveIdx] !== null) {
                newBoard[i] = newBoard[aboveIdx];
                newBoard[aboveIdx] = null;
                break;
              }
              aboveRow--;
            }
            if (newBoard[i] === null) {
              newBoard[i] = getRandomTile();
            }
          }
        }
      }
    } while (matched.size > 0);

    return { newBoard, anyMatch };
  };

  const handleClick = (index) => {
    if (animating) return;
    if (selected === null) {
      setSelected(index);
      return;
    }

    const validMoves = [
      selected - 1,
      selected + 1,
      selected - width,
      selected + width,
    ];

    if (!validMoves.includes(index)) {
      setSelected(null);
      return;
    }

    const tempBoard = [...board];
    [tempBoard[selected], tempBoard[index]] = [tempBoard[index], tempBoard[selected]];
    setBoard(tempBoard);
    setAnimating(true);

    // Give the animation time to play before resolving match
    setTimeout(() => {
      const { newBoard, anyMatch } = handleMatches(tempBoard);
      if (anyMatch) {
        setBoard(newBoard);
      } else {
        // Revert swap
        const revertedBoard = [...tempBoard];
        [revertedBoard[selected], revertedBoard[index]] = [revertedBoard[index], revertedBoard[selected]];
        setBoard(revertedBoard);
      }
      setAnimating(false);
    }, 300);

    setSelected(null);
  };

  return (
    <div className="board-wrapper">
      <div className="board">
        {board.map((tile, i) => (
          <Tile
            key={i}
            index={i}
            width={width}
            tile={tile}
            selected={selected === i}
            animating={animating}
            onClick={() => handleClick(i)}
          />
        ))}
      </div>
    </div>
  );
};

export default Board;
