// src/components/Tile.jsx
import React from "react";
import "./Tile.css";

const cellSize = 60;

const Tile = ({ index, width, tile, selected, onClick, animating }) => {
  const x = (index % width) * cellSize;
  const y = Math.floor(index / width) * cellSize;

  return (
    <div
      className={`tile ${selected ? "selected" : ""}`}
      style={{
        transform: `translate(${x}px, ${y}px)`,
        transition: animating ? "transform 0.3s ease" : "none",
      }}
      onClick={onClick}
    >
      {tile && <img src={tile.img} alt={tile.name} className="tile-img" />}
    </div>
  );
};

export default Tile;
